10	export async function geocodeHandler(req, res, deps = {}) {
11	  if (req.method !== "POST") {
12	    return res.status(405).json({ error: "method_not_allowed" });
13	  }
14	
15	  // Actually validate the session rather than just checking the `rt`
16	  // cookie is present: openSession decrypts and verifies it (shape +
17	  // 30-day lifetime), throwing on anything forged/tampered/expired. Without
18	  // this, any party holding a garbage `rt=x` cookie could hit this endpoint
19	  // as an open, unauthenticated proxy in front of the shared, rate-limited
20	  // MusicBrainz/Nominatim lookups below. Only the "is this real" fact is
21	  // needed here — the decrypted refresh token itself is discarded.
22	  try {
23	    openSession(parseCookies(req.headers.cookie)[COOKIE_NAME]);
24	  } catch {
25	    return res.status(401).json({ error: "no_session" });
26	  }
27	
28	  const { artistId, artistName } = req.body ?? {};
29	  if (!artistId || !artistName) {
30	    return res.status(400).json({ error: "invalid_request" });
31	  }
32	
33	  // Resolved only once the request has cleared every guard above, so a
34	  // rejected request never pays for constructing a real Redis client.
35	  const redis = deps.redis ?? createRedisClient();
36	  const lookup = deps.lookupArtistLocation ?? lookupArtistLocation;
37	  const minIntervalMs = Number(process.env.GEOCODE_MIN_INTERVAL_MS ?? 1100);
38	
39	  // Every Redis call below (cache read, throttle locks, cache write) can
40	  // throw on an Upstash outage. Uncaught, that surfaces as a raw 500 —
41	  // indistinguishable, to the client, from any other failure — and
42	  // useLibraryArtists.js (reasonably) treats a non-200 as "this artist has
43	  // no location" (see its comment). Across an entire outage that marks
44	  // every artist not_found, so the loop finishes and the library reads as
45	  // "resolved successfully, and it's empty." Catching here and returning a
46	  // declared status keeps the failure in-vocabulary and lets the client
47	  // tell it apart from a legitimate negative result.
48	  try {
49	    const cached = await getCachedArtist(redis, artistId);
50	    if (cached) return res.status(200).json(cached);
51	
52	    if (!(await tryAcquireThrottle(redis, "musicbrainz", minIntervalMs))) {
53	      return res
54	        .status(200)
55	        .json({ status: "throttled", retryAfterMs: minIntervalMs });
56	    }
57	
58	    // lookup() does both the MusicBrainz and (if needed) Nominatim calls
59	    // internally; a Nominatim-side throttle is acquired inside it.
60	    const location = await lookup(artistName, {
61	      acquireNominatimThrottle: () =>
62	        tryAcquireThrottle(redis, "nominatim", minIntervalMs),
63	    });
64	    if (location === "THROTTLED") {
65	      return res
66	        .status(200)
67	        .json({ status: "throttled", retryAfterMs: minIntervalMs });
68	    }
69	
70	    const value = location
71	      ? { status: "resolved", ...location, resolvedAt: Date.now() }
72	      : { status: "not_found", resolvedAt: Date.now() };
73	    await setCachedArtist(redis, artistId, value);
74	    return res.status(200).json(value);
75	  } catch (err) {
76	    console.error("geocodeHandler: Redis failure", err);
77	    return res.status(200).json({ status: "unavailable" });
78	  }
79	}
80	
81	export default function handler(req, res) {
82	  return geocodeHandler(req, res);
83	}
